:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #9a9ab0;
  --free: #0f3460;
  --taken: #2a2a40;
  --selected: #e94560;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

header h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: 1px;
  color: var(--accent);
}

.subtitle {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 1rem;
}

.screen {
  text-align: center;
  padding: 8px;
  background: linear-gradient(to bottom, #0f3460, transparent);
  border-radius: 8px;
  color: var(--muted);
  font-size: 0.85rem;
  letter-spacing: 4px;
  font-weight: 600;
}

.seat-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 8px;
}

.seat {
  aspect-ratio: 1 / 1;
  border: 2px solid transparent;
  border-radius: 8px;
  background: var(--free);
  color: var(--text);
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.1s, background 0.15s;
  padding: 0;
  min-width: 0;
}

.seat:hover:not(.taken) {
  background: #1a4a7a;
  transform: scale(1.08);
}

.seat:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.seat.selected {
  background: var(--selected);
  color: #fff;
}

.seat.selected:hover {
  background: #f05a72;
}

.seat.taken {
  background: var(--taken);
  color: #55556a;
  cursor: not-allowed;
  border-color: #3a3a55;
}

.seat:active:not(.taken) {
  transform: scale(0.95);
}

.summary {
  background: rgba(0, 0, 0, 0.25);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.summary-line {
  margin: 0;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.label { color: var(--muted); }
.value { font-weight: 600; text-align: right; }

.total .value {
  color: var(--accent);
  font-size: 1.25rem;
}

.hint {
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  .seat-grid { gap: 5px; }
  .seat { font-size: 0.65rem; border-radius: 6px; }
  header h1 { font-size: 1.4rem; }
}

(function () {
  'use strict';

  var ROWS = ['A', 'B', 'C', 'D', 'E'];
  var COLS = 8;
  var PRICE = 9;
  var TAKEN = ['A1', 'A2', 'B4', 'C7', 'D3', 'E5', 'E6'];

  var state = { selected: [] };

  var grid = document.getElementById('seat-grid');
  var listEl = document.getElementById('selected-list');
  var totalEl = document.getElementById('total-price');

  function seatId(row, col) {
    return row + col;
  }

  function isTaken(id) {
    return TAKEN.indexOf(id) !== -1;
  }

  function renderGrid() {
    var frag = document.createDocumentFragment();
    ROWS.forEach(function (row) {
      for (var c = 1; c <= COLS; c++) {
        var id = seatId(row, c);
        var taken = isTaken(id);
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'seat' + (taken ? ' taken' : '');
        btn.dataset.id = id;
        btn.textContent = id;
        btn.setAttribute('aria-pressed', 'false');
        btn.setAttribute('aria-label', 'Seat ' + id + (taken ? ', unavailable' : ', available'));
        if (taken) {
          btn.disabled = true;
        }
        frag.appendChild(btn);
      }
    });
    grid.appendChild(frag);
  }

  function updateSummary() {
    var sel = state.selected.slice().sort(function (a, b) {
      var ra = a.charAt(0), rb = b.charAt(0);
      if (ra !== rb) return ra < rb ? -1 : 1;
      return parseInt(a.slice(1), 10) - parseInt(b.slice(1), 10);
    });
    listEl.textContent = sel.length ? sel.join(', ') : 'None';
    totalEl.textContent = (sel.length * PRICE) + (sel.length ? ' (' + sel.length + ' × ' + PRICE + ')' : '');
  }

  function toggleSeat(btn) {
    var id = btn.dataset.id;
    if (isTaken(id)) return;
    var idx = state.selected.indexOf(id);
    if (idx === -1) {
      state.selected.push(id);
      btn.classList.add('selected');
      btn.setAttribute('aria-pressed', 'true');
      btn.setAttribute('aria-label', 'Seat ' + id + ', selected');
    } else {
      state.selected.splice(idx, 1);
      btn.classList.remove('selected');
      btn.setAttribute('aria-pressed', 'false');
      btn.setAttribute('aria-label', 'Seat ' + id + ', available');
    }
    updateSummary();
  }

  grid.addEventListener('click', function (e) {
    var btn = e.target.closest('.seat');
    if (btn && !btn.disabled) toggleSeat(btn);
  });

  renderGrid();
  updateSummary();
})();
